export const FALLBACK_IMAGES = {
  POSTERS: {
    BLUE: 'data:image/svg+xml;base64,',
    PURPLE: 'data:image/svg+xml;base64,',
    ORANGE: 'data:image/svg+xml;base64,',
    DARK: 'data:image/svg+xml;base64,'
  },
  BACKGROUND: 'data:image/svg+xml;base64,',
  GALLERY: [
    'data:image/svg+xml;base64,',
    'data:image/svg+xml;base64,',
    'data:image/svg+xml;base64,'
  ]
};

export const getFilmImages = (filmId: string) => {
  const filmImages = {
    interstellar: FREEPIK_IMAGES.SPACE,
    inception: FREEPIK_IMAGES.CITY,
    dune: FREEPIK_IMAGES.DESERT,
    'dark-knight': FREEPIK_IMAGES.NIGHT
  };
  
  return filmImages[filmId as keyof typeof filmImages] || FREEPIK_IMAGES.SPACE;
};

export const getFallbackImage = (type: 'poster' | 'background' | 'gallery', filmId?: string, index?: number) => {
  if (type === 'poster') {
    const posters = {
      interstellar: FALLBACK_IMAGES.POSTERS.BLUE,
      inception: FALLBACK_IMAGES.POSTERS.PURPLE,
      dune: FALLBACK_IMAGES.POSTERS.ORANGE,
      'dark-knight': FALLBACK_IMAGES.POSTERS.DARK
    };
    return filmId ? posters[filmId as keyof typeof posters] || FALLBACK_IMAGES.POSTERS.BLUE : FALLBACK_IMAGES.POSTERS.BLUE;
  }
  
  if (type === 'background') {
    return FALLBACK_IMAGES.BACKGROUND;
  }
  
  if (type === 'gallery') {
    return FALLBACK_IMAGES.GALLERY[index || 0] || FALLBACK_IMAGES.GALLERY[0];
  }
  
  return FALLBACK_IMAGES.POSTERS.BLUE;
};